{"command":"python3 -c "
import csv

# Check for fields that need quoting (contain comma, double quote, or newline)
with open('outputs/t02_eurostat_raw.csv', newline='', encoding='utf-8') as f:
    reader = csv.reader(f)
    header = next(reader)
    quoted_fields = 0
    for row in reader:
        for field in row:
            if ',' in field or '\"' in field or '\n' in field:
                quoted_fields += 1
    print(f'Fields containing special chars: {quoted_fields}')
""}
